pragma solidity >=0.8.2 <0.9.0;

// Полный интерфейс для работы модификатора
interface IERC721 {
    function ownerOf(uint256 tokenId) external view returns (address);
    function getApproved(uint256 tokenId) external view returns (address);
    function isApprovedForAll(address owner, address operator) external view returns (bool);
    function safeTransferFrom(address from, address to, uint256 tokenId) external;
}

interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract Market {
    struct Listing {
        address seller;       
        address paymentToken; 
        uint256 price;        
        bool active;
    }
    // nftContract => tokenId => Listing
    mapping(address => mapping(uint256 => Listing)) public listings;
    mapping(address => bool) public allowedPaymentTokens; 
    uint96 public feeBps;   
    address contractowner = msg.sender;         

    // Событие для индексации подсетью/бэкендом (Graph/Subsequent nodes)
    event ItemListed(address indexed seller, address indexed nft, uint256 indexed tokenId, address paymentToken, uint256 price);

    // модификатор
    modifier nftOwnerOrApproved(address _nft, uint256 _tokenId) {
        address owner = IERC721(_nft).ownerOf(_tokenId);
        require(
            msg.sender == owner || 
            IERC721(_nft).getApproved(_tokenId) == msg.sender || 
            IERC721(_nft).isApprovedForAll(owner, msg.sender), 
            "Not owner or approved"
        );
        _;
    }
    // Добавлен модификатор и проверки безопасности
    function listItem (address _nft, uint256 _tokenId, address _paymentToken, uint256 _price) public nftOwnerOrApproved(_nft, _tokenId) {
        require(_price > 0, "Price must be above zero");
        require(allowedPaymentTokens[_paymentToken], "Payment token not whitelisted");
        
        // Проверяем, дал ли владелец маркетплейсу право забрать NFT при покупке
        address owner = IERC721(_nft).ownerOf(_tokenId);
        require(
            IERC721(_nft).getApproved(_tokenId) == address(this) || 
            IERC721(_nft).isApprovedForAll(owner, address(this)),
            "Market not approved to transfer NFT"
        );

        listings[_nft][_tokenId] = Listing({
            seller: owner, // Фиксируем реального владельца, а не msg.sender (который мог быть оператором)
            paymentToken: _paymentToken,
            price: _price,
            active: true
        });
        emit ItemListed(owner, _nft, _tokenId, _paymentToken, _price);
    }
    //перепроверить функцыю апдейта
    function updateListing(address _nft, uint256 _tokenId, address _paymentToken, uint256 _price) public nftOwnerOrApproved(_nft, _tokenId) {
        require(_price > 0, "Price must be above zero");
        require(allowedPaymentTokens[_paymentToken], "Payment token not whitelisted");
        
        // Проверяем, дал ли владелец маркетплейсу право забрать NFT при покупке
        address owner = IERC721(_nft).ownerOf(_tokenId);
        require(
            IERC721(_nft).getApproved(_tokenId) == address(this) || 
            IERC721(_nft).isApprovedForAll(owner, address(this)),
            "Market not approved to transfer NFT"
        );
        listings[_nft][_tokenId] = Listing({
            seller: owner, // Фиксируем реального владельца, а не msg.sender (который мог быть оператором)
            paymentToken: _paymentToken,
            price: _price,
            active: true
        });
        emit ItemListed(owner, _nft, _tokenId, _paymentToken, _price);
    }
    function cancelListing (address _nft, uint256 _tokenId) public nftOwnerOrApproved(_nft, _tokenId) {
        require(msg.sender == contractowner,"Not owner or approved");
        delete listings[_nft][_tokenId]; 
    }
    function buyItem (address _nft, uint256 _tokenId, address _expectedToken, uint256 _expectedPrice) public {
        
    }
}

